/bin/bash -lc "python3 - <<'PY'
import gzip, subprocess, os, tempfile
# read mystery
sets={f'S{i}':[] for i in range(1,7)}
with gzip.open('mystery.peak.set.q1.bed.gz','rt') as f:
    for line in f:
        p=line.split()
        if p[3] in sets: sets[p[3]].append((p[0],int(p[1]),int(p[2])))
# write temp dirs
import pathlib
td=pathlib.Path('[REDACTED LOCAL PATH]'); td.mkdir(exist_ok=True)
for s, arr in sets.items():
    with open(td/f'{s}.bed','w') as f:
        for x in arr: f.write(f'{x[0]}\\t{x[1]}\\t{x[2]}\\n')
for s in sorted(sets):
    total=len(sets[s])
    p=subprocess.run(['bedtools','intersect','-u','-a',str(td/f'{s}.bed'),'-b','cpeaks_repo/map2cpeak/cpeaks_hg38.bed.gz'],capture_output=True,text=True)
    inter=len(p.stdout.splitlines())
    print(s,total,inter,round(inter/total,4))
PY"

